import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue.
 * @param {Array<{ number: string, customerId: string, dueDate: string, status: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format to compare against
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} Sorted most overdue first
 */
export function overdueInvoices(invoices, asOf) {
  const asOfDate = new Date(`${asOf}T00:00:00Z`);

  const overdue = invoices
    .filter((invoice) => {
      // Only include 'issued' or 'partially_paid' statuses
      if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
        return false;
      }

      // Only include invoices where dueDate is before asOf
      const dueDate = new Date(`${invoice.dueDate}T00:00:00Z`);
      return dueDate < asOfDate;
    })
    .map((invoice) => {
      const dueDate = new Date(`${invoice.dueDate}T00:00:00Z`);
      const daysOverdue = Math.floor((asOfDate - dueDate) / (1000 * 60 * 60 * 24));
      const due = balanceDue(invoice);

      return {
        number: invoice.number,
        customerId: invoice.customerId,
        dueDate: invoice.dueDate,
        daysOverdue,
        due,
      };
    })
    // Sort by daysOverdue descending (most overdue first)
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get VAT summary for invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} Sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    // Only include 'issued', 'partially_paid', or 'paid' statuses
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      const vatRate = line.vatRate ?? 0;
      const lineTotal = roundCents(line.qty * line.unitPrice);
      const discount = roundCents(lineTotal * ((line.discountPercent ?? 0) / 100));
      const base = roundCents(lineTotal - discount);
      const vat = roundCents(base * (vatRate / 100));

      if (!vatMap.has(vatRate)) {
        vatMap.set(vatRate, { rate: vatRate, base: 0, vat: 0 });
      }

      const entry = vatMap.get(vatRate);
      entry.base = roundCents(entry.base + base);
      entry.vat = roundCents(entry.vat + vat);
    }
  }

  // Convert map to array and sort by rate descending
  return Array.from(vatMap.values()).sort((a, b) => b.rate - a.rate);
}

