});

test('lateFee calculates with VAT included in total', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 20 }],
  };

