  // 12000 (10000 + 2000 VAT) * 0.0004 * 10 = 48
  assert.equal(fee, 48);
});

test('lateFee handles long overdue periods', () => {
  const invoice = {
    dueDate: '2024-01-01',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-31');
  // 364 days overdue (2024 is a leap year, so 366 days, but Jan 1 to Dec 31 is 364 days)
  // 10000 * 0.0004 * 364 = 1456
  assert.equal(fee, 1456);
});

